import java.util.*;

// Base class of flow algorithms
class FlowBase<Cap, Cost> {
    static class Edge<Cap, Cost> {
        int src, dst;
        Cap cap;
        Cost cost;
        Edge<Cap, Cost> rev;

        Edge(int src, int dst, Cap cap, Cost cost, Edge<Cap, Cost> rev) {
            this.src = src;
            this.dst = dst;
            this.cap = cap;
            this.cost = cost;
            this.rev = rev;
        }
    }

    protected ArrayList<ArrayList<Edge<Cap, Cost>>> adj;

    FlowBase(int n) {
        adj = new ArrayList<>(n);
        for (int i = 0; i < n; ++i) adj.add(new ArrayList<>());
    }

    int size() {
        return adj.size();
    }

    ArrayList<Edge<Cap, Cost>> get(int node) {
        return adj.get(node);
    }

    void addEdge(int src, int dst, Cap cap, Cost cost) {
        if (src < 0 || src >= size() || dst < 0 || dst >= size()) {
            throw new IndexOutOfBoundsException();
        }
        if (cap instanceof Integer && ((Integer) cap) <= 0) return;
        if (cap instanceof Long && ((Long) cap) <= 0) return;
        Edge<Cap, Cost> e = new Edge<>(src, dst, cap, cost, null);
        Edge<Cap, Cost> rev = new Edge<>(dst, src, null, null, e);
        e.rev = rev;
        // For the reverse edge, we need a zero capacity and opposite cost
        // Since Java generics don't allow arithmetic, we'll assume Integer/Long and set appropriately.
        if (cap instanceof Integer) {
            rev.cap = 0;
            rev.cost = (Cost) (cost instanceof Integer ? (Integer)(-(Integer)cost) : (Long)(-(Long)cost));
        } else if (cap instanceof Long) {
            rev.cap = (Cap) Long.valueOf(0);
            rev.cost = (Cost) (cost instanceof Long ? -(Long)cost : (Integer)(-(Integer)cost));
        }
        adj.get(src).add(e);
        adj.get(dst).add(rev);
    }
}

class MinCostFlow<Cap, Cost> extends FlowBase<Cap, Cost> {
    private Cost minCost, totalCost;
    private Cap[] supp;
    private Cost[] ptnl, dist;
    private Edge<Cap, Cost>[] last;

    MinCostFlow(int n) {
        super(n + 2);
        minCost = null;
        totalCost = null;
        supp = (Cap[]) new Object[n + 2];
        ptnl = (Cost[]) new Object[n + 2];
        dist = (Cost[]) new Object[n + 2];
        last = (Edge<Cap, Cost>[]) new Edge[n + 2];
        // Initialize supp to zero
        for (int i = 0; i < supp.length; ++i) {
            if (Cap.class == Integer.class) {
                supp[i] = (Cap) Integer.valueOf(0);
                ptnl[i] = (Cost) Long.valueOf(0);
                dist[i] = (Cost) Long.valueOf(Long.MAX_VALUE);
            } else {
                supp[i] = (Cap) Long.valueOf(0);
                ptnl[i] = (Cost) Long.valueOf(0);
                dist[i] = (Cost) Long.valueOf(Long.MAX_VALUE);
            }
        }
        minCost = (Cost) (Cap.class == Integer.class ? Long.valueOf(0) : Long.valueOf(0));
        totalCost = (Cost) (Cap.class == Integer.class ? Long.valueOf(0) : Long.valueOf(0));
    }

    void addEdge(int src, int dst, Cap cap, Cost cost) {
        if (src == dst) return;
        if (cap instanceof Integer && (Integer) cap <= 0) return;
        if (cap instanceof Long && (Long) cap <= 0) return;
        // If cost is negative, handle special
        boolean neg = false;
        if (cost instanceof Integer && (Integer) cost < 0) neg = true;
        if (cost instanceof Long && (Long) cost < 0) neg = true;
        if (neg) {
            // Subtract from supp
            // We'll assume cap is integer for simplicity
            if (cap instanceof Integer) {
                int c = (Integer) cap;
                int co = (Integer) cost;
                supp[src] = (Cap) Integer.valueOf((Integer) supp[src] - c);
                supp[dst] = (Cap) Integer.valueOf((Integer) supp[dst] + c);
                minCost = (Cost) Long.valueOf((Long) minCost + (long) c * co);
                totalCost = (Cost) Long.valueOf((Long) totalCost - (long) c * co);
                super.addEdge(dst, src, cap, (Cost) Integer.valueOf(-co));
            } else {
                long c = (Long) cap;
                long co = (Long) cost;
                supp[src] = (Cap) Long.valueOf((Long) supp[src] - c);
                supp[dst] = (Cap) Long.valueOf((Long) supp[dst] + c);
                minCost = (Cost) Long.valueOf((Long) minCost + c * co);
                totalCost = (Cost) Long.valueOf((Long) totalCost - c * co);
                super.addEdge(dst, src, cap, (Cost) Long.valueOf(-co));
            }
        } else {
            if (cap instanceof Integer) {
                totalCost = (Cost) Long.valueOf((Long) totalCost + (long)(Integer) cap * (Integer) cost);
            } else {
                totalCost = (Cost) Long.valueOf((Long) totalCost + (Long) cap * (Long) cost);
            }
            super.addEdge(src, dst, cap, cost);
        }
    }

    void supply(int node, Cap vol) {
        if (vol instanceof Integer) {
            supp[node] = (Cap) Integer.valueOf((Integer) supp[node] + (Integer) vol);
        } else {
            supp[node] = (Cap) Long.valueOf((Long) supp[node] + (Long) vol);
        }
    }

    boolean solve() {
        if (size() <= 1) return false;
        int src = size() - 2;
        int dst = src + 1;
        long flow = 0; // using long for accumulation
        long suppSum = 0;
        for (int node = 0; node < size(); ++node) {
            if (supp[node] instanceof Integer) {
                suppSum += (Integer) supp[node];
                if ((Integer) supp[node] > 0) {
                    flow += (Integer) supp[node];
                    addEdge(src, node, supp[node], (Cost) (supp[node] instanceof Integer ? Integer.valueOf(0) : Long.valueOf(0)));
                } else if ((Integer) supp[node] < 0) {
                    addEdge(node, dst, (Cap) Integer.valueOf(-(Integer) supp[node]), (Cost) (supp[node] instanceof Integer ? Integer.valueOf(0) : Long.valueOf(0)));
                }
            } else {
                suppSum += (Long) supp[node];
                if ((Long) supp[node] > 0) {
                    flow += (Long) supp[node];
                    addEdge(src, node, supp[node], (Cost) (supp[node] instanceof Integer ? Integer.valueOf(0) : Long.valueOf(0)));
                } else if ((Long) supp[node] < 0) {
                    addEdge(node, dst, (Cap) Long.valueOf(-(Long) supp[node]), (Cost) (supp[node] instanceof Integer ? Integer.valueOf(0) : Long.valueOf(0)));
                }
            }
            // reset supp after processing
            if (supp[node] instanceof Integer) supp[node] = (Cap) Integer.valueOf(0);
            else supp[node] = (Cap) Long.valueOf(0);
        }
        if (suppSum != 0) return false;
        while (flow > 0) {
            if (!dijkstra(src, dst)) return false;
            long resid = flow;
            for (int node = dst; node != src; node = last[node].src) {
                Edge<Cap, Cost> e = last[node];
                if (e.cap instanceof Integer) {
                    resid = Math.min(resid, (Integer) e.cap);
                } else {
                    resid = Math.min(resid, (Long) e.cap);
                }
            }
            flow -= resid;
            // minCost += ptnl[dst] * resid
            if (ptnl[dst] instanceof Long) {
                minCost = (Cost) Long.valueOf((Long) minCost + (Long) ptnl[dst] * resid);
            }
            for (int node = dst; node != src; node = last[node].src) {
                Edge<Cap, Cost> e = last[node];
                if (e.cap instanceof Integer) {
                    e.cap = (Cap) Integer.valueOf((Integer) e.cap - (int) resid);
                    e.rev.cap = (Cap) Integer.valueOf((Integer) e.rev.cap + (int) resid);
                } else {
                    e.cap = (Cap) Long.valueOf((Long) e.cap - resid);
                    e.rev.cap = (Cap) Long.valueOf((Long) e.rev.cap + resid);
                }
            }
        }
        return true;
    }

    private boolean dijkstra(int src, int dst) {
        final long infty = Long.MAX_VALUE / 2;
        // initialize dist to infty, ptnl unchanged
        for (int i = 0; i < size(); ++i) {
            dist[i] = (Cost) (Long) infty;
        }
        dist[src] = (Cost) (Long) 0L;
        PriorityQueue<Map.Entry<Long, Integer>> pq = new PriorityQueue<>(Comparator.comparingLong(Map.Entry::getKey));
        pq.offer(new AbstractMap.SimpleEntry<>(0L, src));
        while (!pq.isEmpty()) {
            Map.Entry<Long, Integer> top = pq.poll();
            long ndist = -top.getKey();
            int now = top.getValue();
            if (!(dist[now] instanceof Long)) continue;
            long curDist = (Long) dist[now];
            if (curDist != ndist) continue;
            // update potential
            long ptnlNow = (Long) ptnl[now];
            ptnl[now] = (Cost) (Long) (ptnlNow + ndist);
            // mark as processed by setting dist to -1
            dist[now] = (Cost) (Long) (-1L);
            for (Edge<Cap, Cost> e : get(now)) {
                if (dist[e.dst] instanceof Long) {
                    long dDst = (Long) dist[e.dst];
                    if (dDst == -1) continue; // visited
                    long cap = (e.cap instanceof Integer) ? (Integer) e.cap : (Long) e.cap;
                    if (cap <= 0) continue;
                    long ptnlDst = (Long) ptnl[e.dst];
                    long newDist = ptnlNow + (Long) e.cost - ptnlDst;
                    if (newDist < dDst) {
                        dist[e.dst] = (Cost) (Long) newDist;
                        last[e.dst] = e;
                        pq.offer(new AbstractMap.SimpleEntry<>(-newDist, e.dst));
                    }
                }
            }
        }
        // check if dst is processed
        if (dist[dst] instanceof Long) {
            long d = (Long) dist[dst];
            return d == -1;
        } else {
            return false;
        }
    }

    Cost optimal() {
        solve();
        return minCost;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        MinCostFlow<Integer, Long> mcf = new MinCostFlow<>(6100);
        final int tlim = 105;

        for (int i = 0; i < k; ++i) {
            int j = sc.nextInt() - 1;
            mcf.supply(j, 1);
        }

        for (int i = 0; i < m; ++i) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            for (int t = 0; t < tlim; ++t) {
                int nu = u + n;
                int nv = v + n;
                for (int x = 0; x < k; ++x) {
                    mcf.addEdge(u, nv, 1, (long) (c + d * (x * 2 + 1)));
                    mcf.addEdge(v, nu, 1, (long) (c + d * (x * 2 + 1)));
                }
                u = nu;
                v = nv;
            }
        }

        for (int i = 1; i < n; ++i) {
            for (int t = 0; t < tlim; ++t) {
                mcf.addEdge(n * t + i, n * (t + 1) + i, k, c);
            }
        }

        int dst = mcf.size() - 1;
        mcf.supply(dst, -k);
        for (int t = 0; t <= tlim; ++t) {
            mcf.addEdge(t * n, dst, k, 0);
        }

        System.out.println(mcf.optimal());
    }
}
